contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address loggerToToggle, address otherAddr, bytes32 b1, bytes32 b2, bytes32 b3) public payable {
        require(loggerToToggle != address(0) && otherAddr != address(0));

        // Record initial approval statuses via public getter
        bool before_logger = c.approvedToLog(loggerToToggle); if (__ESBMC_reverted()) return;
        bool before_other = c.approvedToLog(otherAddr); if (__ESBMC_reverted()) return;

        // Try to call various logging methods as this contract (msg.sender == address(this))
        // First ensure this contract is not mistakenly approved: if it is, flip it off using onlyOwner cannot be called here
        // We cannot call setApprovedLogger because onlyOwner restricts it and InvMutTest is not owner of c.
        // So we proceed with current msg.sender approval status = c.approvedToLog(address(this))
        bool meApproved = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // Attempt several log calls that should return false if not approved, true if approved.
        bool r1 = c.logCreated(otherAddr); if (__ESBMC_reverted()) return;
        bool r2 = c.logGotRedemptionSignature(b1, b2, b3); if (__ESBMC_reverted()) return;
        bool r3 = c.logRegisteredPubkey(b1, b2); if (__ESBMC_reverted()) return;
        bool r4 = c.logSetupFailed(); if (__ESBMC_reverted()) return;
        bool r5 = c.logRedemptionRequested(otherAddr, b1, 1, abi.encodePacked(uint8(0x01)), 0, abi.encodePacked(uint8(0x02))); if (__ESBMC_reverted()) return;
        bool r6 = c.logFunded(); if (__ESBMC_reverted()) return;
        bool r7 = c.logCourtesyCalled(); if (__ESBMC_reverted()) return;
        bool r8 = c.logStartedLiquidation(true); if (__ESBMC_reverted()) return;
        bool r9 = c.logRedeemed(b1); if (__ESBMC_reverted()) return;
        bool r10 = c.logLiquidated(); if (__ESBMC_reverted()) return;
        bool r11 = c.logExitedCourtesyCall(); if (__ESBMC_reverted()) return;
        bool r12 = c.logFraudDuringSetup(); if (__ESBMC_reverted()) return;

        // After making logging calls, assert that approvedLoggers mapping did not change for observed addresses
        bool after_logger = c.approvedToLog(loggerToToggle); if (__ESBMC_reverted()) return;
        bool after_other = c.approvedToLog(otherAddr); if (__ESBMC_reverted()) return;

        // General rule: none of these logging calls change approval status of arbitrary addresses;
        // additionally, each call's boolean result must equal whether this contract was approved at call time.
        assert(
            after_logger == before_logger
            && after_other == before_other
            && r1 == meApproved
            && r2 == meApproved
            && r3 == meApproved
            && r4 == meApproved
            && r5 == meApproved
            && r6 == meApproved
            && r7 == meApproved
            && r8 == meApproved
            && r9 == meApproved
            && r10 == meApproved
            && r11 == meApproved
            && r12 == meApproved
        );
    }

    receive() external payable {}
}

