    }

    function _run(address loggerToToggle, address otherAddr, bytes32 b1, bytes32 b2, bytes32 b3) internal {
        vm.assume(loggerToToggle != address(0) && otherAddr != address(0));
        bool before_logger;
        try c.approvedToLog(loggerToToggle) returns (bool __r) { before_logger = __r; } catch { return; }
        bool before_other;
        try c.approvedToLog(otherAddr) returns (bool __r) { before_other = __r; } catch { return; }
        bool meApproved;
        try c.approvedToLog(address(this)) returns (bool __r) { meApproved = __r; } catch { return; }
        bool r1;
        try c.logCreated(otherAddr) returns (bool __r) { r1 = __r; } catch { return; }
        bool r2;
        try c.logGotRedemptionSignature(b1, b2, b3) returns (bool __r) { r2 = __r; } catch { return; }
        bool r3;
        try c.logRegisteredPubkey(b1, b2) returns (bool __r) { r3 = __r; } catch { return; }
        bool r4;
        try c.logSetupFailed() returns (bool __r) { r4 = __r; } catch { return; }
        bool r5;
        try c.logRedemptionRequested(otherAddr, b1, 1, abi.encodePacked(uint8(0x01)), 0, abi.encodePacked(uint8(0x02))) returns (bool __r) { r5 = __r; } catch { return; }
        bool r6;
        try c.logFunded() returns (bool __r) { r6 = __r; } catch { return; }
        bool r7;
        try c.logCourtesyCalled() returns (bool __r) { r7 = __r; } catch { return; }
        bool r8;
        try c.logStartedLiquidation(true) returns (bool __r) { r8 = __r; } catch { return; }
        bool r9;
        try c.logRedeemed(b1) returns (bool __r) { r9 = __r; } catch { return; }
        bool r10;
        try c.logLiquidated() returns (bool __r) { r10 = __r; } catch { return; }
        bool r11;
        try c.logExitedCourtesyCall() returns (bool __r) { r11 = __r; } catch { return; }
        bool r12;
        try c.logFraudDuringSetup() returns (bool __r) { r12 = __r; } catch { return; }
        bool after_logger;
        try c.approvedToLog(loggerToToggle) returns (bool __r) { after_logger = __r; } catch { return; }
        bool after_other;
        try c.approvedToLog(otherAddr) returns (bool __r) { after_other = __r; } catch { return; }
        assertTrue(after_logger == before_logger
            && after_other == before_other
            && r1 == meApproved
            && r2 == meApproved
            && r3 == meApproved
            && r4 == meApproved
            && r5 == meApproved
            && r6 == meApproved
            && r7 == meApproved
            && r8 == meApproved
            && r9 == meApproved
            && r10 == meApproved
            && r11 == meApproved
            && r12 == meApproved);
    }

    function testFuzz_run(address loggerToToggle, address otherAddr, bytes32 b1, bytes32 b2, bytes32 b3) public {
        vm.assume(loggerToToggle.code.length == 0 && uint160(loggerToToggle) > 0xffff && loggerToToggle != address(this) && loggerToToggle != address(c) && loggerToToggle != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && loggerToToggle != 0x000000000000000000636F6e736F6c652e6c6f67 && loggerToToggle != 0x4e59b44847b379578588920cA78FbF26c0B4956C && loggerToToggle != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(otherAddr.code.length == 0 && uint160(otherAddr) > 0xffff && otherAddr != address(this) && otherAddr != address(c) && otherAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && otherAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && otherAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && otherAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(loggerToToggle, otherAddr, b1, b2, b3);
    }

    receive() external payable {}
